      const error = state.errors[name];
      const value = escapeHtml(state.values[name]);

      return `
        <div class="form-field ${error ? "has-error" : ""}">
          <label for="${name}">${config.label}${config.required ? " *" : ""}</label>
          <input
            id="${name}"
            name="${name}"
            type="${config.type}"
            placeholder="${config.placeholder}"
            value="${value}"
